"""ds4_hip_gemv: hand-HIP small-M block-scaled fp8 GEMV for gfx1151 decode.

Streams the fp8 weight directly, at half the bytes of the dequant-cached bf16
path, with in-register dequant.

LAYOUT -- the thing an earlier version of this file got wrong. vLLM stores
these weights [N,K] row-major but PADS each row: observed strides are
(K+256, 1), so weight.is_contiguous() is False. The previous eligible() gated
on is_contiguous(), so it returned False for every weight in the serve and the
kernel never ran once -- while being benchmarked against a dense [N,K] tensor
it was never given. Always pass the real row stride (weight.stride(0)).

It replaces a bf16 path that materialises a dense bf16 copy and therefore
reads twice the bytes.

Kernel: libds4fp8gemv.so (source container/native/ds4_fp8_gemv_hip.cpp),
wave32-native, 8 waves/wg. It is purely memory-bound -- deleting all of its
arithmetic does not make it faster -- so the layout exists to keep each
workgroup's DRAM footprint contiguous: the waves split one row's K between
them and the workgroup steps to adjacent rows, rather than each wave owning
rows a full K-stride apart.
"""
import ctypes
import os

import torch

_LIB_PATHS = [
    os.path.join(os.path.dirname(os.path.abspath(__file__)), "libds4fp8gemv.so"),
    "/opt/venv/lib64/python3.12/site-packages/libds4fp8gemv.so",
]

_lib = None
_SCALE_CACHE: dict = {}


def _load():
    global _lib
    if _lib is None:
        for p in _LIB_PATHS:
            if os.path.exists(p):
                _lib = ctypes.CDLL(p)
                break
        if _lib is None:
            raise RuntimeError("libds4fp8gemv.so not found")
        _lib.ds4_fp8_gemv.restype = ctypes.c_int
        _lib.ds4_fp8_gemv.argtypes = (
            [ctypes.c_void_p] * 4 + [ctypes.c_int] * 4 + [ctypes.c_void_p]
        )
    return _lib


def eligible(m: int, weight: torch.Tensor) -> bool:
    if not (1 <= m <= 8 and weight.dtype == torch.float8_e4m3fn):
        return False
    N, K = weight.shape
    ldw = weight.stride(0)
    # rows may be padded, but must be k-major and stay 16B-aligned so the
    # kernel's uint4 loads are legal
    if weight.stride(1) != 1 or ldw < K or (ldw & 15):
        return False
    # the contiguous-march kernel needs K in whole 512B quads, and one row must
    # fit a workgroup's 8 waves; above K=4096 it falls back to a layout that
    # loses to hipblaslt, so leave those on the bf16 path
    if not (512 <= K <= 4096 and (K & 511) == 0):
        return False
    rows_per_wg = 2 if K >= 4096 else 8
    return (N % rows_per_wg) == 0 and (N & 15) == 0


def _scales(weight: torch.Tensor, weight_scale: torch.Tensor) -> torch.Tensor:
    """Block scales as [N/128, K/128] fp32 contiguous, cached per weight.

    Serve weights are immortal, so data_ptr keying is safe here (unlike
    benches, which recycle allocations).
    """
    if weight_scale.dtype == torch.float32 and weight_scale.is_contiguous():
        return weight_scale
    key = weight.data_ptr()
    s = _SCALE_CACHE.get(key)
    if s is None:
        s = weight_scale.to(torch.float32).contiguous()
        _SCALE_CACHE[key] = s
    return s


def fp8_gemv(x: torch.Tensor, weight: torch.Tensor,
             weight_scale: torch.Tensor) -> torch.Tensor:
    """x [M,K] bf16 contiguous, weight [N,K] fp8 (rows may be padded),
    weight_scale [N/128, K/128]. Returns bf16 [M,N]."""
    lib = _load()
    ws = _scales(weight, weight_scale)
    M, K = x.shape
    N = weight.shape[0]
    out = torch.empty(M, N, dtype=torch.bfloat16, device=x.device)
    rc = lib.ds4_fp8_gemv(
        x.data_ptr(), weight.data_ptr(), ws.data_ptr(), out.data_ptr(),
        M, N, K, weight.stride(0), torch.cuda.current_stream().cuda_stream)
    if rc != 0:
        raise RuntimeError(f"ds4_fp8_gemv rc={rc}")
    return out
